import pandas as pd
import numpy as np

# Define indicators
def williams_r(high, low, close, period=14):
    highest_high = high.rolling(window=period).max()
    lowest_low = low.rolling(window=period).min()
    wr = -100 * ((highest_high - close) / (highest_high - lowest_low))
    return wr

def obv(close, volume):
    obv = np.zeros(len(close))
    obv[0] = volume[0]
    for i in range(1, len(close)):
        if close[i] > close[i-1]:
            obv[i] = obv[i-1] + volume[i]
        elif close[i] < close[i-1]:
            obv[i] = obv[i-1] - volume[i]
        else:
            obv[i] = obv[i-1]
    return obv

def volume_profile(volume, period=20):
    vp = np.zeros(len(volume))
    for i in range(period, len(volume)):
        vp[i] = np.mean(volume[i-period:i])
    return vp

# Define entry and exit rules
def check_long_entry(wr, obv, vp):
    return wr > -50 and obv[-1] > obv[-2] and vp[-1] > vp[-2]

def check_short_entry(wr, obv, vp):
    return wr < -50 and obv[-1] < obv[-2] and vp[-1] < vp[-2]

def check_long_exit(wr, obv, vp):
    return wr < -50 and obv[-1] < obv[-2] and vp[-1] < vp[-2]

def check_short_exit(wr, obv, vp):
    return wr > -50 and obv[-1] > obv[-2] and vp[-1] > vp[-2]

# Define risk management and position sizing
def calculate_stop_loss(price, percentage):
    return price * (1 - percentage/100)

def calculate_take_profit(price, percentage):
    return price * (1 + percentage/100)

def calculate_position_size(account_size, fraction):
    return account_size * fraction

# Backtest the strategy
def backtest(data):
    signals = np.zeros(len(data))
    positions = np.zeros(len(data))
    account_size = 100000
    fraction = 0.01

    for i in range(1, len(data)):
        wr = williams_r(data['High'], data['Low'], data['Close'], period=14)
        obv_val = obv(data['Close'], data['Volume'])
        vp = volume_profile(data['Volume'], period=20)

        if check_long_entry(wr[i], obv_val[i], vp[i]):
            signals[i] = 1
            positions[i] = calculate_position_size(account_size, fraction)
            stop_loss = calculate_stop_loss(data['Close'][i], 2)
            take_profit = calculate_take_profit(data['Close'][i], 5)
        elif check_short_entry(wr[i], obv_val[i], vp[i]):
            signals[i] = -1
            positions[i] = calculate_position_size(account_size, fraction)
            stop_loss = calculate_stop_loss(data['Close'][i], 2)
            take_profit = calculate_take_profit(data['Close'][i], 5)
        elif check_long_exit(wr[i], obv_val[i], vp[i]):
            signals[i] = 0
            positions[i] = 0
        elif check_short_exit(wr[i], obv_val[i], vp[i]):
            signals[i] = 0
            positions[i] = 0

    return signals, positions

# Load market data
data = pd.read_csv('market_data.csv')

# Backtest the strategy
signals, positions = backtest(data)

# Print the results
print('Signals:', signals)
print('Positions:', positions)
